T[33] = { { "Coup tordu", "Le palefroi corrompu étourdit tous ceux qui sont près de lui pendant 3 secondes, et ils subissent plus de dégâts physiques. Le destrier des ténèbres n’a aucune technique." } }
T[34] = { { "Drain du boucher", "Draine 350 points de mana à sa cible au corps à corps : un tank qui a du mana le sent passer." } }
