T[36] = { { "Lumière sacrée", "Se soigne ou soigne un allié (incantation de 2,5 secondes). Interromps-le." }, { "Bouclier divin", "Le rend insensible à tous les dégâts et à tous les sorts pendant 10 secondes." }, { "Marteau de la justice", "Étourdit un joueur pendant 4 secondes." } }
T[37] = { { "Appelle à l’aide", "Quand tu l’engages, il appelle les créatures à moins de 30 mètres. Nettoie autour de lui avant." }, { "Rage hurlante", "À 60 %, 40 % et 20 % de vie, ses coups deviennent plus forts." } }
T[38] = { { "Enchaînement", "Frappe sa cible et le joueur le plus proche d’elle." }, { "Brise-genou", "Ralentit les déplacements de sa cible pendant 10 secondes." } }
T[39] = { note = "Ils arrivent à quatre après la mort de Fenrus le Dévoreur : Arugal apparaît un instant et les appelle.", { "Sombre offrande", "Soigne un autre marcheur du Vide. Tuez-les un par un." } }
T[40] = { { "Bave toxique", "Des dégâts de Nature toutes les 6 secondes et du mana drainé, pendant 2 minutes. Guéris le poison." } }
T[41] = { { "Des worgs en renfort", "Plus le combat dure, plus il a de worgs avec lui : un worg pâle au bout de 30 à 45 secondes, puis un worg écumant, puis une horreur lupine." } }
T[42] = { { "Eclair de Vide", "Un trait d’Ombre de 3 secondes sur le tank, encore et encore. Interromps-le." }, { "Malédiction d’Arugal", "Change un joueur autre que le tank en Glouton d’Ombrecroc qui se bat pour lui pendant 10 secondes. Retire la malédiction." }, { "Port de l'ombre", "Il se téléporte entre son rebord, le rebord du haut et l’escalier." }, { "Coup de Tonnerre", "Quand le tank arrive sur lui : des dégâts de Nature et un étourdissement de 5 secondes autour de lui." } }
T[43] = { { "Piétiner", "Frappe tous ceux qui se tiennent près de lui." } }
T[44] = { { "Fourche d'éclairs", "Des dégâts de Nature dans un cône devant elle (incantation de 2 secondes). Reste hors du cône." }, { "Nova de givre", "Gèle sur place tous ceux qui sont près d’elle jusqu’à 8 secondes." }, { "Lenteur", "Ralentit les déplacements et les attaques d’un joueur pendant 10 secondes." } }
T[45] = { { "Filet", "Immobilise un joueur sur place pendant 10 secondes." } }
T[46] = { note = "Clique sur la pierre de la Brasse dans l’eau : il en surgit.", { "Eclair de givre", "Il garde ses distances pour le lancer : des dégâts de Givre et un ralentissement." }, { "Nova de givre", "Immobilise tous ceux qui sont près de lui jusqu’à 8 secondes." } }
T[47] = { { "Sommeil", "Endort tous ceux qui sont près de lui jusqu’à 10 secondes. Des dégâts réveillent un dormeur." }, { "Attaque mentale", "Des dégâts d’Ombre sur un joueur (incantation de 1,5 seconde)." } }
T[48] = { note = "Il attend dans une grotte sous l’eau, sous le temple du Seigneur du Crépuscule Kelris, et beaucoup de groupes le ratent. Nage sous le temple pour l’atteindre." }
T[49] = { note = "Une fois le Seigneur du Crépuscule Kelris mort, allume les quatre feux d’Aku’mai de sa salle, l’un après l’autre. Chacun amène une vague de créatures. Quand elles sont toutes mortes, la porte d’Aku’mai s’ouvre.", { "Nuage empoisonné", "Des dégâts de Nature toutes les 5 secondes pendant 45 secondes à tous ceux qui sont proches." }, { "Rage frénétique", "Sous 30 % de vie : des rafales d’attaques 75 % plus rapides, encore et encore." } }
T[50] = { { "Bouclier de foudre", "La foudre frappe quiconque le touche. Un prêtre ou un chaman peut le retirer." }, { "Eclair", "Il garde ses distances pour le lancer. Interromps-le." } }
T[51] = { { "Heurt de bouclier", "Frappe le tank et l’étourdit 2 secondes." }, { "Fuit chercher de l’aide", "À 15 % de vie, il s’enfuit chercher de l’aide. Achève-le avant qu’il ne s’éloigne." } }
T[52] = { { "Fuit chercher de l’aide", "À 15 % de vie, il s’enfuit chercher de l’aide. Achève-le avant qu’il ne s’éloigne." } }
T[53] = { { "Rosser", "De temps en temps, deux attaques en plus : de gros coups sur le tank." }, { "Enrager", "À 30 % de vie, il attaque 30 % plus vite jusqu’à la fin du combat." } }
T[54] = { { "Chaîne d'éclairs", "Un éclair qui rebondit de joueur en joueur (incantation de 2 secondes). Interromps-le." }, { "Furie sanguinaire", "Accélère ses attaques ou celles d’un allié de 30 % pendant 30 secondes. Un prêtre ou un chaman peut la retirer." } }
T[55] = { { "Frappe", "Frappe la cible et lui inflige les dégâts de l'arme plus 5. Garde le tank en vie." } }
T[56] = { { "Bombe fumigène", "Étourdit tous ceux qui sont près de lui pendant 4 secondes." }, { "Cri de guerre", "Plus de puissance d’attaque pour lui et ses alliés pendant 2 minutes." }, { "Fuit chercher de l’aide", "À 15 % de vie, il s’enfuit chercher de l’aide. Achève-le avant qu’il ne s’éloigne." } }
T[57] = { { "Beaucoup de points de vie", "Rien de spécial vu pendant le combat : il frappe et il a beaucoup de vie. Il rôde dans le marais du début parmi des crocilisques élites, alors nettoie-les d’abord ou attire-le loin d’eux." } }
T[58] = { note = "Tue la matriarche raptor dans les hautes herbes. Une vague de raptors arrive à sa mort, et Dent-Sombre accourt une fois qu’ils sont morts.", { "Des raptors dans l’herbe", "De petits raptors surgissent de l’herbe quand tu la traverses et te font saigner." }, { "La vague avant lui", "Tue tous les raptors de la vague avant qu’il arrive. Un groupe est mort à son premier essai avec Dent-Sombre et plusieurs raptors sur lui en même temps." }, { "Peur", "Le tank est apeuré plusieurs fois pendant ce combat. Le Totem de séisme d’un chaman aide." } }
T[59] = { { "Le camp Gueule-de-dragon", "Il se tient dans un camp Gueule-de-dragon. Ses groupes s’attirent facilement un par un : prends-les d’abord un à la fois. Le combat lui-même est court, rien de spécial vu pour l’instant." } }
T[60] = { note = "Il reste immobile au bout du chemin des araignées. Clique sur le petit panneau à côté de lui pour le réveiller.", { "Remise à zéro de la menace", "Il remet sa menace à zéro et change de cible pendant le combat. Dégâts, ralentissez quand le tank le perd. Tank, reprends-le tout de suite." } }
T[61] = { note = "Il se tient près d’un cercle rituel dans les égouts, entouré de nécromanciens du Kirin Tor.", { "Frénésie impie", "Il accélère ses attaques de 75 % pendant 20 secondes. C’est de la magie : l’Expiation d’un chaman ou la Dissipation de la magie d’un prêtre la lui retire." }, { "Rosser", "De temps en temps, il frappe deux fois de plus d’un coup, et Frappe ajoute des dégâts à son coup suivant : le tank encaisse de gros coups." }, { "Réanimation morbide", "Des squelettes se relèvent sans arrêt autour du cercle pendant le combat. Ils sont faibles : tue-les à mesure qu’ils arrivent." }, { "Désarmement", "Il désarme le tank pendant environ 6 secondes." } }
T[62] = { note = "Elle n’est pas là au départ. Dans les égouts, après Atrexis, nettoie la salle nord-est, celle aux étals de marché avec un petit cercle d’invocation rose (pas le grand cercle d’Atrexis). Un joueur qui a le Tome de Dalaran sur lui clique ensuite sur le cercle, et Lyn sort de la grande porte ronde grillagée. Pour obtenir le tome, ramasse le Tome noir posé sur la table de la salle de l’archimage Arugal, au Donjon d’Ombrecroc, une fois Arugal tué, puis utilise-le au Leyline Focus, un cristal bleu dans une arrière-salle de Moulin-de-l’Ambre, dans la forêt des Pins-Argentés.", { "Salve de Traits de l'ombre", "Des traits de l’ombre sur tout le monde à 30 mètres d’elle." }, { "Malédiction des épines", "1,5 seconde d’incantation : une malédiction de 3 minutes qui blesse de temps en temps le joueur quand il attaque. Retire-la." }, { "Squelettes", "Des squelettes se relèvent et combattent à ses côtés. Tue-les." } }
T[63] = { { "Déflagration focalisée", "Après 3 secondes d’incantation, un rayon part devant lui pendant 6 secondes et frappe quatre fois par seconde. Sors de sa trajectoire dès le début de l’incantation." }, { "Éclair des arcanes", "Son attaque sur le tank entre deux rayons, 1,5 seconde d’incantation." } }
T[64] = { { "Manamorphose", "Transforme un joueur en animal pendant 8 secondes. C’est de la magie : dissipe-la." }, { "Silence", "Réduit au silence pendant 10 secondes. Soigneurs, gardez vos distances." }, { "Arcane Manalings", "Il appelle sans arrêt de petits Arcane Manalings. Tue-les avec des dégâts de zone." } }
T[65] = { { "Disfonctionnement", "2 secondes d’incantation, puis pendant 6 secondes de l’énergie arcanique frappe tout le monde à 25 mètres toutes les 2 secondes, pour environ 140 points de dégâts à chaque fois. Distance, restez au-delà de 25 mètres ; mêlée, sortez pendant l’incantation." }, { "Angry Tomes", "Des Angry Tomes te foncent dessus sur le chemin. Tue-les avant d’engager le boss." } }
T[66] = { { "Débiliter", "2 secondes d’incantation : une énergie arcanique draine jusqu’à 200 points de mana à tout le monde à 45 mètres de lui." }, { "Drain de vitalité", "Un effet magique sur le tank : environ 65 points de dégâts des Arcanes toutes les 2 secondes pendant 10 secondes. Dissipe-le." }, { "Sa salle", "Les créatures encore en vie dans sa salle rejoignent le combat quand vous l’engagez. Videz la salle d’abord." } }
T[67] = { note = "Il attend derrière une barrière magique au centre de la ville, gardée par des Suffused Treants. Tue les tréants, puis parle au magus Fansy Goodbringer, juste au sud de la barrière : il la fait tomber.", { "Gangrebraises", "Des lianes filent vers un joueur et frappent tout le monde à 5 mètres de lui, puis laissent des vapeurs toxiques au sol. Sors des vapeurs." }, { "Piétiner", "Il piétine les joueurs à côté de lui pour environ 100 points de dégâts physiques." }, { "Enchevêtrement", "Enracine jusqu’à deux joueurs près de lui pendant quelques secondes et les blesse dans la durée. C’est de la magie : dissipez-la." } }
T[68] = { note = "L’archimage Modera ouvre au groupe un portail vers la chambre pourpre : il mène à lui.", { "Mana bondissant", "Un orbe file vers un joueur au hasard puis revient vers lui. Tous ceux qu’il traverse subissent des dégâts des Arcanes et sont réduits au silence 6 secondes : ne te place pas entre lui et ce joueur." }, { "Métamorphose de masse", "Quand il n’a plus de mana, il transforme tout le groupe en animaux pendant 8 secondes, puis canalise Évocation pendant 6 secondes pour la remplir." }, { "Lenteur", "Ralentit tout le monde autour de lui pendant 3 secondes : attaques et incantations 30 % plus lentes, déplacement 70 % plus lent." }, { "Restez dans la salle", "Si quelqu’un sort de la salle pendant le combat, il revient à pleine vie." } }
T[69] = { { "Filet", "Immobilise tous ceux qui sont près de lui pendant 10 secondes." }, { "Ralentissement", "Ralentit les attaques et les déplacements d’un joueur pendant 10 secondes, et peut l’étourdir." }, { "Invocation d'une blatte mécanique", "Appelle des blattes mécaniques. Sa Mise à jour les tue et le soigne." } }
T[70] = { note = "Parle au maître-dynamiteur Emi Courtemèche et protège-la pendant qu’elle fait sauter les deux entrées de grotte. Des troggs arrivent par vagues, puis Grubbis vient avec Mâchouilleur." }
T[71] = { { "Mégavolt", "Des dégâts de Nature dans un cône devant lui (incantation de 2 secondes). Seul le tank se met devant." }, { "Chaîne d'éclairs", "Un éclair qui rebondit sur les joueurs proches (incantation de 2,5 secondes). Interromps-le." } }
T[72] = { { "Faucher la foule", "Frappe tous ceux qui sont près de lui et interrompt leurs sorts. Lanceurs de sorts et soigneurs, gardez vos distances." }, { "Frappe en arc de cercle", "Frappe tout le monde dans un cône devant lui." }, { "Piétiner", "Frappe tous ceux qui se tiennent près de lui." } }
T[73] = { { "Invocation d'un serviteur enflammé", "Appelle deux serviteurs enflammés au début du combat." }, { "Boule de feu", "Il garde ses distances pour le lancer. Interromps-le." }, { "Bouclier de feu II", "Des dégâts de Feu à tous ceux qui sont près de lui pendant une minute. Un prêtre ou un chaman peut le retirer." } }
T[74] = { { "Bombes ambulantes", "Il allume une à une les têtes de gnome autour de la salle, et chacune lâche des bombes ambulantes qui explosent en atteignant un joueur. Le bouton à côté d’une tête l’éteint. Sous la moitié de sa vie, il les allume plus vite." }, { "Repousser au loin", "Repousse le tank. Sous la moitié de sa vie, cela touche tout le monde autour de lui." } }
T[75] = { { "Invocation de l'esprit du sanglier", "Appelle un Esprit de sanglier à ses côtés toutes les 30 à 45 secondes (incantation de 1,5 seconde). Tue chacun avant que le suivant arrive." }, { "Salve de guérison", "Sous 75 % de vie, il se soigne, et le soin rebondit sur deux alliés proches (incantation de 2,5 secondes). Interromps-le." } }
T[76] = { { "Emprise", "Prend le contrôle d’un joueur autre que sa cible pendant 15 secondes (incantation de 2 secondes). Interromps-le, ou dissipe l’effet sur le joueur." }, { "Trait de l'ombre", "Il garde ses distances pour le lancer. Interromps-le." } }
T[77] = { { "Appelle à l’aide", "Quand tu l’engages, il appelle les créatures à moins de 15 mètres, dont les deux Lanceurs de Tranchebauge à ses côtés. Garde l’un des deux sous contrôle pendant le combat." }, { "Coup de tonnerre", "Toutes les 8 à 14 secondes : des dégâts de Nature à tous ceux qui sont près de lui, et leurs attaques et déplacements sont ralentis pendant 10 secondes." } }
T[78] = { { "Barrage tourbillonnant", "Frappe tous ceux qui se tiennent près de lui." }, { "Aura d’épines", "Quiconque le frappe, lui ou un allié proche (Seigneur Brusquebroche compris), subit des dégâts de Nature." } }
T[79] = { note = "Une protection ferme sa grotte. Tue les deux Gardiens de la Tête de Mort postés devant : elle tombe quand les deux sont morts.", { "Laissé pour mort", "Toutes les 21 à 35 secondes, il frappe un joueur autre que sa cible, qui tombe comme mort et ne peut plus attaquer ni lancer de sort. Bouger y met fin." }, { "Saccager", "Toutes les 25 à 31 secondes : frappe tous ceux qui sont près de lui et les étourdit 2,5 secondes." }, { "Enrager", "À 60 % de vie, puis à 40 %, il attaque 60 % plus vite et frappe plus fort pendant 2 minutes." } }
T[80] = { note = "Une chauve-souris rare : elle n’est pas là à chaque passage. Quand elle y est, elle attend dans un petit renfoncement de la paroi de la grotte aux chauves-souris, près de Charlga Trancheflanc." }
T[81] = { { "Chaîne d'éclairs", "Elle garde ses distances et le lance encore et encore : un éclair qui rebondit sur 3 joueurs au plus (incantation de 2,5 secondes). Interromps-le." }, { "Pureté", "Toutes les 9 à 15 secondes, elle est insensible à toutes les attaques et à tous les sorts pendant 2 secondes." }, { "Rénovation", "Soigne un allié blessé, ou elle-même, sur 15 secondes. Un prêtre ou un chaman peut le retirer." } }
T[82] = { { "Invocation d'un grondeur terrestre", "Un Grondeur des pierres l’accompagne et se bat à ses côtés." }, { "Eclair", "Il garde ses distances pour le lancer. Interromps-le." }, { "Fuit chercher de l’aide", "À 15 % de vie, il s’enfuit chercher de l’aide. Achève-le avant qu’il ne s’éloigne." } }
T[83] = { { "Invocation d'un grondeur terrestre", "Un Grondeur des pierres l’accompagne et se bat à ses côtés." }, { "Eclair", "Il garde ses distances pour le lancer. Interromps-le." } }
T[84] = { { "Mot de l'ombre : Douleur", "Dégâts d’ombre sur sa cible toutes les 3 secondes pendant 18 secondes. Une dissipation de la magie l’enlève." } }
T[85] = { note = "Environ une partie sur trois, l’un des trois rares du cimetière se tient à l’un des six endroits de la carte : Azshir the Sleepless, Fallen Champion ou Ironspine.", { "Appel de la tombe", "Au bout de 60 secondes, des dégâts d’ombre au joueur (incantation de 2 secondes). Un mage ou un druide peut la retirer avant." }, { "Terrifier", "Fait fuir un joueur de peur pendant 4 secondes." }, { "Siphon d’âme", "Sous la moitié de sa vie, il draine un joueur et le joueur le plus proche de lui pendant 12 secondes, et se soigne." } }
T[86] = { note = "Environ une partie sur trois, l’un des trois rares du cimetière se tient à l’un des six endroits de la carte : Azshir the Sleepless, Fallen Champion ou Ironspine.", { "Enchaînement", "Frappe sa cible et le joueur le plus proche d’elle." }, { "Exécution", "Frappe fort une cible à 20 % de vie ou moins. Garde le tank au-dessus." } }
T[87] = { note = "Environ une partie sur trois, l’un des trois rares du cimetière se tient à l’un des six endroits de la carte : Azshir the Sleepless, Fallen Champion ou Ironspine.", { "Malédiction de faiblesse", "Réduit les dégâts physiques de tous ceux qui sont à moins de 30 mètres pendant 2 minutes. Un mage ou un druide peut la retirer." }, { "Nuage empoisonné", "Des dégâts de Nature toutes les 5 secondes pendant 45 secondes à tous ceux qui sont proches." } }
T[88] = { { "Dards de flammes", "Une colonne de flammes là où se tient un joueur (incantation de 3 secondes) : des dégâts de Feu, puis encore toutes les 3 secondes pendant 9 secondes. Sors-en." }, { "Nova de feu", "Des dégâts de Feu à tous ceux qui sont à moins de 10 mètres de lui." }, { "Horion de flammes", "Des dégâts de Feu à un joueur, puis encore toutes les 3 secondes pendant 12 secondes. Une dissipation de la magie l’enlève." }, { "Trait de l'ombre", "Il garde ses distances pour le lancer. Interromps-le." } }
T[89] = { { "Chiens de chasse écarlates", "Trois chiens l’accompagnent et attaquent avec lui, et il leur donne aussi Furie sanguinaire. Tue-les en premier." }, { "Furie sanguinaire", "Accélère ses attaques ou celles d’un allié de 30 % pendant 30 secondes. Un prêtre ou un chaman peut la retirer." }, { "Cri de guerre", "Plus de puissance d’attaque pour lui et ses chiens pendant 3 minutes." } }
T[90] = { { "Détonation", "À mi-vie, il s’enferme 8 secondes dans une Bulle des arcanes et lance Détonation (incantation de 5 secondes) : de lourds dégâts de Feu à tous ceux qui sont à moins de 30 mètres. Sors de portée avant l’explosion, puis reviens." }, { "Métamorphose", "Transforme en mouton un joueur autre que sa cible pendant 20 secondes au plus (incantation de 1,5 seconde). Interromps-le, ou dissipe l’effet sur le joueur." }, { "Silence", "Réduit au silence tous ceux qui sont à moins de 15 mètres pendant 10 secondes (incantation de 1,5 seconde). Si tu soignes, reste plus loin." }, { "Explosion des arcanes", "Toutes les quelques secondes, des dégâts des Arcanes à tous ceux qui sont à moins de 10 mètres. À distance, garde tes distances." } }
T[91] = { { "Tourbillon", "Toutes les 15 à 25 secondes, il tourbillonne pendant 10 secondes et frappe tous ceux qui sont près de lui. Au corps à corps, recule jusqu’à la fin." }, { "Enchaînement", "Frappe sa cible et le joueur le plus proche d’elle." }, { "Enrager", "À 30 % de vie, il attaque 60 % plus vite et frappe plus fort pendant 2 minutes." }, { "Jeunes recrues écarlates", "À sa mort, 20 Jeunes recrues écarlates entrent par la porte de la salle et attaquent. Reste avec ton groupe et utilise des dégâts de zone." } }
T[92] = { { "Malédiction de Tuten'kash", "Malédiction qui réduit de 15 % la vitesse d'incantation et ralentit de 18 % les attaques des joueurs proches, pendant 15 minutes. Retire la malédiction." } }
T[93] = { { "Boule de feu", "Une boule de feu sur sa cible, encore et encore. Interromps-le." }, { "Nova de feu", "Dégâts de Feu à tous les joueurs proches de lui. Éloigne-toi quand il l'incante." } }
T[94] = { { "Nuée maléfique", "Un nuage de maladie autour de lui blesse tous les joueurs proches toutes les 3 secondes. Combats à distance ou guéris la maladie." }, { "Enrager", "Il s'enrage et augmente ses dégâts et sa vitesse d'attaque pendant 2 minutes. Soigne davantage le tank." } }
T[95] = { { "Emprise", "Contrôle un joueur pendant 10 secondes. Dissipe l'effet et empêche le joueur contrôlé de blesser le groupe." }, { "Mot de l'ombre : Douleur", "Dégâts d'Ombre toutes les 3 secondes pendant 18 secondes. Dissipe-le." }, { "Soins", "Se soigne ou soigne un allié. Interromps l'incantation." }, { "Trait de l'ombre", "Un éclair de dégâts d'Ombre sur une cible, incantation de 3 secondes. Interromps-le." } }
T[96] = { { "Colère d'Amnennar", "Repousse une cible. Reviens en position." }, { "Eclair de givre", "Un éclair de givre qui ralentit sa cible, lancé encore et encore. Interromps-le." }, { "Nova de givre", "Dégâts de Givre et immobilisation de tous les joueurs proches. Dissipe l'immobilisation." } }
T[97] = { { "Toucher de Flétrissure", "Maladie qui inflige des dégâts d'Ombre et draine du mana toutes les 10 secondes pendant 3 minutes, au profit du lanceur. Guéris-la, surtout sur les lanceurs de sorts." }, { "Puanteur pourrie", "Réduit de 50 la Force et l'Agilité des joueurs proches pendant 10 secondes et les empêche de lancer des sorts. Lanceurs de sorts, reste loin de lui." } }
T[98] = { note = "Il est allongé par terre dans la petite salle à côté de l’autel, comme mort, et se relève quand on l’attaque.", { "Peur", "Fait fuir un joueur de terreur jusqu’à 8 secondes (incantation de 1,5 seconde). Interromps-le." }, { "Sommeil", "Endort tous ceux qui sont près de lui jusqu’à 10 secondes. Des dégâts réveillent un dormeur." }, { "Malédiction du Sang", "Un joueur subit plus de dégâts physiques pendant 10 minutes (incantation de 2 secondes). Un mage ou un druide peut la retirer." }, { "Soins", "À 30 % de vie, il se soigne (incantation de 3 secondes). Interromps-le." } }
T[99] = { { "Appelle à l’aide", "Quand tu l’engages, il appelle tous les défenseurs écarlates à moins de 80 mètres. Nettoie la cathédrale avant de l’engager." }, { "Marteau de la justice", "Étourdit un joueur pendant 5 secondes." }, { "Bouclier divin", "À mi-vie, il devient insensible à tous les dégâts et à tous les sorts pendant 12 secondes." }, { "Aura de vindicte", "Des dégâts du Sacré à quiconque le frappe au corps à corps." } }
T[100] = { note = "Quand Mograine tombe, il fait seulement le mort : elle sort de la salle derrière l’autel et attaque.", { "Résurrection écarlate", "À mi-vie, elle endort toute la salle jusqu’à 10 secondes, court vers Mograine et le ressuscite. Il lui rend toute sa vie avec Imposition des mains, et les deux te combattent ensemble." }, { "Châtiment sacré", "Des dégâts du Sacré à sa cible (incantation de 2,5 secondes). Interromps-la." }, { "Soins", "Soigne le plus blessé de ses alliés, Mograine compris (incantation de 3 secondes). Interromps-la." }, { "Mot de pouvoir : Bouclier", "La protège des dégâts jusqu’à 30 secondes. Un prêtre ou un chaman peut le retirer." } }
T[101] = { { "Assaut fulgurant", "Augmente sa vitesse de déplacement pendant 3 secondes et ajoute des dégâts à sa première attaque. Soigne le joueur touché." } }
T[102] = { { "Frappe", "Une frappe de mêlée aux dégâts augmentés sur sa cible. Soigne le tank." } }
T[103] = { { "Heurt de bouclier", "Frappe sa cible et l'étourdit pendant 2 secondes. Soigne pendant l'étourdissement." } }
T[104] = { { "Eclair", "Un éclair de Nature sur sa cible. Interromps-le." }, { "Chaîne d'éclairs", "Un éclair de Nature qui rebondit sur 3 joueurs maximum. Interromps-le et écarte-toi des autres." } }
T[105] = { { "Frappe en arc de cercle", "Un coup balayant tous les joueurs devant elle. Reste hors de son arc frontal." }, { "Repousser au loin", "Inflige des dégâts supplémentaires à sa cible et la repousse. Soigne le tank." }, { "Choc martial", "Repousse et étourdit tous les joueurs proches pendant 5 secondes. Soigne pendant l'étourdissement." } }
T[106] = { { "Tempêtes de sable", "Invoque une tempête de sable qui combat pour lui pendant 30 secondes. Tue-la ou éloigne-toi d'elle." }, { "Tempêtes de sable", "Invoque une tempête de sable qui combat pour lui pendant 30 secondes. Tue-la ou éloigne-toi d'elle." } }
T[107] = { { "Fouet de flammes", "Dégâts de Feu qui réduisent la résistance au Feu de sa cible pendant 45 secondes. Soigne le tank." }, { "Amplifier flammes", "Augmente de 100 les dégâts de Feu subis par sa cible pendant 30 secondes. Soigne le tank plus fort." }, { "Nova de feu", "Dégâts de Feu à tous les joueurs proches de lui. Éloigne-toi quand il l'incante." } }
T[108] = { { "Furie sanguinaire", "Augmente la vitesse d'attaque d'un allié de 30% pendant 30 secondes. Attends-toi à des coups plus rapides sur le tank." }, { "Chaîne d'éclairs", "Un éclair qui rebondit sur 3 joueurs maximum. Interromps-le et écarte-toi des autres." }, { "Eclair", "Un éclair de Nature sur sa cible. Interromps-le." }, { "Rapetisser", "Réduit de 1 la Force et l'Endurance des joueurs proches pendant 2 minutes. L'effet est mineur." } }
T[109] = { { "Tremblement de terre", "Étourdit tous les joueurs proches de lui. Soigne pendant l'étourdissement." }, { "Enrager", "Augmente sa vitesse d'attaque de 60% et ses dégâts physiques de 50 pendant 2 minutes. Soigne le tank plus fort." }, { "Réveiller les Gardiens terrestres", "Réveille des gardiens de terre qui attaquent le groupe. Tue-les ou éloigne-les du soigneur." }, { "Réveiller le Garde de la Banque", "Réveille des gardes de la chambre qui rejoignent le combat. Occupe-toi des ennemis supplémentaires avant d'être submergé." } }
